    "file_path": "app/static/js/recipe_search.js",
    "content": "(function () {\n    const input = document.getElementById(\"recipe-search\");\n    if (!input) return;\n\n    const grid = document.querySelector(\".recipe-grid\");\n    const cards = grid ? Array.from(grid.querySelectorAll(\"article[data-search]\")) : [];\n    const empty = document.getElementById(\"recipe-search-empty\");\n    const emptyText = empty ? empty.querySelector(\"small\") || empty : null;\n    const count = document.getElementById(\"recipe-count\");\n    const originalCountText = count ? count.textContent : null;\n    const filter = document.getElementById(\"recipe-type-filter\");\n    const typeOptions = filter ? Array.from(filter.querySelectorAll('input[name=\"recipe-type\"]')) : [];\n\n    const typeLabels = {\n        all: [\"recipe\", \"recipes\"],\n        recipe: [\"full recipe\", \"full recipes\"],\n        idea: [\"recipe idea\", \"recipe ideas\"],\n    };\n\n    function selectedType() {\n        const checked = typeOptions.find((option) => option.checked);\n        return checked && typeLabels[checked.value] ? checked.value : \"all\";\n    }\n\n    function apply() {\n        const query = input.value.trim().toLowerCase();\n        const tokens = query ? query.split(/\\s+/) : [];\n        const type = selectedType();\n        let visible = 0;\n\n        for (const card of cards) {\n            const haystack = card.dataset.search || \"\";\n            const typeMatch = type === \"all\" || card.dataset.recordType === type;\n            const match = typeMatch && tokens.every((t) => haystack.includes(t));\n            card.hidden = !match;\n            if (match) visible++;\n        }\n\n        const [singular, plural] = typeLabels[type];\n        const noun = visible === 1 ? singular : plural;\n\n        if (empty) {\n            empty.hidden = visible !== 0;\n            if (emptyText && visible === 0) {\n                emptyText.textContent = tokens.length\n                    ? `No ${plural} match \"${input.value.trim()}\". Try a different search or filter.`\n                    : `No ${plural} in your collection yet.`;\n            }\n        }\n\n        if (count) {\n            if (tokens.length === 0 && type === \"all\") {\n                count.textContent = originalCountText;\n            } else if (tokens.length === 0) {\n                count.textContent = `${visible} ${noun} in your collection`;\n            } else {\n                count.textContent = `${visible} matching ${noun}`;\n            }\n        }\n    }\n\n    input.addEventListener(\"input\", apply);\n    for (const option of typeOptions) {\n        option.addEventListener(\"change\", apply);\n    }\n    // Browsers may restore the search text or filter choice on back navigation.\n    apply();\n})();\n"
