    "content": "// Behaviour tests for app/static/js/recipe_search.js using a minimal fake DOM.\n// Run with `node --test tests/js/` (also run by tests/test_recipe_search_js.py).\nimport assert from \"node:assert/strict\";\nimport { readFileSync } from \"node:fs\";\nimport test from \"node:test\";\nimport vm from \"node:vm\";\n\nconst SCRIPT = readFileSync(new URL(\"../../app/static/js/recipe_search.js\", import.meta.url), \"utf8\");\n\nclass FakeElement {\n    constructor(props = {}) {\n        Object.assign(this, { hidden: false, textContent: \"\", value: \"\", checked: false, dataset: {} }, props);\n        this.listeners = {};\n        this.children = [];\n    }\n\n    addEventListener(type, listener) {\n        (this.listeners[type] ||= []).push(listener);\n    }\n\n    dispatch(type) {\n        for (const listener of this.listeners[type] || []) listener();\n    }\n\n    querySelector(selector) {\n        return this.querySelectorAll(selector)[0] || null;\n    }\n\n    querySelectorAll(selector) {\n        return this.children.filter((child) => child.matches === selector);\n    }\n}\n\nfunction setup(entries, { search = \"\", type = \"all\" } = {}) {\n    const input = new FakeElement({ value: search });\n    const cards = entries.map(\n        ([title, recordType]) =>\n            new FakeElement({ title, matches: \"article[data-search]\", dataset: { search: title.toLowerCase(), recordType } }),\n    );\n    const grid = new FakeElement();\n    grid.children = cards;\n    const options = [\"all\", \"recipe\", \"idea\"].map(\n        (value) => new FakeElement({ value, checked: value === type, matches: 'input[name=\"recipe-type\"]' }),\n    );\n    const filter = new FakeElement();\n    filter.children = options;\n    const emptyText = new FakeElement({ textContent: \"No matching recipes.\", matches: \"small\" });\n    const empty = new FakeElement({ hidden: true });\n    empty.children = [emptyText];\n    const count = new FakeElement({\n        textContent: `${entries.length} recipe${entries.length === 1 ? \"\" : \"s\"} in your collection`,\n    });\n    const byId = {\n        \"recipe-search\": input,\n        \"recipe-search-empty\": empty,\n        \"recipe-count\": count,\n        \"recipe-type-filter\": filter,\n    };\n    const document = {\n        getElementById: (id) => byId[id] || null,\n        querySelector: (selector) => (selector === \".recipe-grid\" ? grid : null),\n    };\n    vm.runInNewContext(SCRIPT, { document });\n\n    return {\n        input,\n        empty,\n        emptyText,\n        count,\n        options,\n        visibleTitles: () => cards.filter((card) => !card.hidden).map((card) => card.title),\n        search(text) {\n            input.value = text;\n            input.dispatch(\"input\");\n        },\n        choose(value) {\n            for (const option of options) option.checked = option.value === value;\n            options.find((option) => option.value === value).dispatch(\"change\");\n        },\n    };\n}\n\nconst ENTRIES = [\n    [\"Chicken curry\", \"recipe\"],\n    [\"Chicken shawarma bowls\", \"idea\"],\n    [\"Lemon tart\", \"recipe\"],\n    [\"Thai noodle salad\", \"idea\"],\n];\n\ntest(\"shows all entries in their original order by default\", () => {\n    const page = setup(ENTRIES);\n\n    assert.deepEqual(page.visibleTitles(), ENTRIES.map(([title]) => title));\n    assert.equal(page.count.textContent, \"4 recipes in your collection\");\n    assert.equal(page.empty.hidden, true);\n});\n\ntest(\"filters to full recipes or recipe ideas\", () => {\n    const page = setup(ENTRIES);\n\n    page.choose(\"recipe\");\n    assert.deepEqual(page.visibleTitles(), [\"Chicken curry\", \"Lemon tart\"]);\n    assert.equal(page.count.textContent, \"2 full recipes in your collection\");\n\n    page.choose(\"idea\");\n    assert.deepEqual(page.visibleTitles(), [\"Chicken shawarma bowls\", \"Thai noodle salad\"]);\n    assert.equal(page.count.textContent, \"2 recipe ideas in your collection\");\n\n    page.choose(\"all\");\n    assert.deepEqual(page.visibleTitles(), ENTRIES.map(([title]) => title));\n    assert.equal(page.count.textContent, \"4 recipes in your collection\");\n});\n\ntest(\"combines the filter with search and keeps the search text when switching\", () => {\n    const page = setup(ENTRIES);\n\n    page.search(\"chicken\");\n    assert.deepEqual(page.visibleTitles(), [\"Chicken curry\", \"Chicken shawarma bowls\"]);\n    assert.equal(page.count.textContent, \"2 matching recipes\");\n\n    page.choose(\"idea\");\n    assert.equal(page.input.value, \"chicken\");\n    assert.deepEqual(page.visibleTitles(), [\"Chicken shawarma bowls\"]);\n    assert.equal(page.count.textContent, \"1 matching recipe idea\");\n\n    page.choose(\"recipe\");\n    assert.equal(page.input.value, \"chicken\");\n    assert.deepEqual(page.visibleTitles(), [\"Chicken curry\"]);\n    assert.equal(page.count.textContent, \"1 matching full recipe\");\n\n    page.search(\"\");\n    assert.deepEqual(page.visibleTitles(), [\"Chicken curry\", \"Lemon tart\"]);\n    assert.equal(page.count.textContent, \"2 full recipes in your collection\");\n});\n\ntest(\"explains when a search and filter combination matches nothing\", () => {\n    const page = setup(ENTRIES);\n\n    page.choose(\"idea\");\n    page.search(\"tart\");\n\n    assert.deepEqual(page.visibleTitles(), []);\n    assert.equal(page.empty.hidden, false);\n    assert.equal(page.emptyText.textContent, 'No recipe ideas match \"tart\". Try a different search or filter.');\n    assert.equal(page.count.textContent, \"0 matching recipe ideas\");\n\n    page.choose(\"all\");\n    assert.deepEqual(page.visibleTitles(), [\"Lemon tart\"]);\n    assert.equal(page.empty.hidden, true);\n});\n\ntest(\"explains when the collection has no entries of the chosen type\", () => {\n    const page = setup([[\"Chicken curry\", \"recipe\"]]);\n\n    page.choose(\"idea\");\n\n    assert.deepEqual(page.visibleTitles(), []);\n    assert.equal(page.empty.hidden, false);\n    assert.equal(page.emptyText.textContent, \"No recipe ideas in your collection yet.\");\n    assert.equal(page.count.textContent, \"0 recipe ideas in your collection\");\n});\n\ntest(\"applies search text and filter restored by the browser on load\", () => {\n    const page = setup(ENTRIES, { search: \"chicken\", type: \"recipe\" });\n\n    assert.deepEqual(page.visibleTitles(), [\"Chicken curry\"]);\n    assert.equal(page.count.textContent, \"1 matching full recipe\");\n});\n"
